// ── Utility Functions ─────────────────────────────────────────────────

export function getKLMLAByConstituency(acNo: number): LegislatorProfile | undefined {
  return KL_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getKLMLAByName(name: string): LegislatorProfile | undefined {
  const q = name.toLowerCase();
  return KL_MLA_PROFILES.find(p =>
    p.name.toLowerCase().includes(q) || p.displayName?.toLowerCase().includes(q)
  );
}

export function getKLMLAsByParty(party: string): LegislatorProfile[] {
  return KL_MLA_PROFILES.filter(p => p.currentParty === party);
}

export function getKLFemaleMLAs(): LegislatorProfile[] {
  return KL_MLA_PROFILES.filter(p => p.gender === 'F');
}

export function getKLCrorepatiMLAs(): LegislatorProfile[] {
  return KL_MLA_PROFILES.filter(p =>
    p.financialHistory.some(f => f.isCrorepati)
  );
}

export function getKLMLAsWithCriminalCases(): LegislatorProfile[] {
  return KL_MLA_PROFILES.filter(p => p.criminalRecord.hasCriminalCases);
}

export function getKLMultiTermMLAs(): LegislatorProfile[] {
  return KL_MLA_PROFILES.filter(p => p.termsServed >= 2);
}

export function getKLPartyStrength(): Record<string, number> {
  const strength: Record<string, number> = {};
  for (const p of KL_MLA_PROFILES) {
    strength[p.currentParty] = (strength[p.currentParty] || 0) + 1;
  }
  return strength;
}

export function getKLWealthStats() {
  const sorted = [...KL_MLA_PROFILES]
    .filter(p => p.financialHistory[0]?.totalAssets > 0)
    .sort((a, b) => (b.financialHistory[0]?.totalAssets || 0) - (a.financialHistory[0]?.totalAssets || 0));
  return {
    richest: sorted[0],
    poorest: sorted[sorted.length - 1],
    totalMLAs: sorted.length,
    crorepatis: sorted.filter(p => p.financialHistory[0]?.isCrorepati).length,
    avgNetWorth: sorted.reduce((s, p) => s + (p.financialHistory[0]?.netWorth || 0), 0) / sorted.length,
  };
}

export function getKLMLAProfile(acNo: number): LegislatorProfile | undefined {
  return getKLMLAByConstituency(acNo);
}
export function getAllKLMLAs(): LegislatorProfile[] {
  return KL_MLA_PROFILES;
}
